head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > P > ref]<br/>Calendar 컴포넌트의 입력값에 바인딩할 DataCollection 정보를 설정합니다.",
    "validation" : [
        "접근 가능한 DataCollection 의 컬럼을 'data:[DataCollection ID].[Key 또는 Column ID]' 형식으로 설정합니다.",
        "DataMap 에 바인딩된 경우 해당 Key 값이 컴포넌트의 입력값으로 설정됩니다.",
        "DataList 에 바인딩된 경우 선택된 Row 의 해당 컬럼 값이 컴포넌트의 입력값으로 설정됩니다.",
        "바인딩된 DataList 의 선택이 변경되어 입력값이 변경된 경우 onchange 이벤트가 발생합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        ref : con_ref.getText(),
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onchange"]);

    // comp 생성 함수 호출 (dynamicCreate)
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:calendar ' + strNameSpace + ' ' + cList + ' ' + eList + ' style="width:280px; height:300px;" calendarValueType="yearMonthDate"></w2:calendar>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "calendar",
        strTarget,
        grp_comp
    );
}



scwin.btn_getValue_onclick = function (e) {
    let rtn = target1.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("입력값 확인 : " + rtn);
};



scwin.btn_setRowposition1_onclick = function (e) {
    dlt_ref.setRowPosition(0);
};



scwin.btn_setRowposition2_onclick = function (e) {
    dlt_ref.setRowPosition();
};



scwin.con_ref_onchange = function (info) {
    if (con_ref.getText() !== "data:dlt_ref.label") {
        btn_setRowposition1.setDisabled(true);
        btn_setRowposition2.setDisabled(true);
    } else {
        btn_setRowposition1.setDisabled(false);
        btn_setRowposition2.setDisabled(false);
    }
};



// validation: 바인딩된 DataList 의 선택이 변경되어 입력값이 변경된 경우 onchange 이벤트가 발생함
scwin.target1_onchange = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onchange 이벤트 발생] getValue()='" + target1.getValue() + "'");
};
